//! The reference world generated by the vanilla server (`mc_testkit::worldref`): its level.dat round-trips exactly.

use mc_nbt::{CompoundTag, NbtAccounter};
use mc_world::level_storage::*;
use std::path::Path;

fn read(path: &Path) -> CompoundTag {
    read_compressed(path, &mut NbtAccounter::unlimited_heap()).unwrap()
}

fn assert_level_dat_round_trips(path: &Path) {
    let root = read(path);
    let data = root.get_compound("Data").expect("Data");
    let parsed = PrimaryLevelData::parse(data, SpecialWorldProperty::None);
    let last_played = data.get_long("LastPlayed").unwrap();
    assert_eq!(&parsed.to_tag_at(None, last_played), data, "{}", path.display());
    // the root has only `Data`
    assert_eq!(root.len(), 1);
}

#[test]
#[ignore = "oracle: needs the vanilla reference world (generated by mc_testkit::worldref)"]
fn worldref_level_dat_round_trips() {
    assert_level_dat_round_trips(&mc_testkit::worldref().expect("reference world").join("level.dat"));
}
